// Eight original Quest Clash games. Shared pets, learning loadout and colour themes; distinct rules.
const GAME_MODES=[
{id:'arena',name:'Quest Clash Arena',tag:'LIVE CO-OP + SOLO',icon:'✦',colour:'#a4e5c4',desc:'Outsmart shared bots, dodge their fire and conquer the guardian.',help:'Move, aim automatically, and use your equipped weapon. Live rooms support 2–4 players.'},
{id:'rally',name:'Turbo Tails Rally',tag:'CAR RACING',icon:'➟',colour:'#ffca8c',desc:'Steer a pet-powered kart through a winding crystal course.',help:'Steer with the joystick or arrows. Hold Boost to accelerate. Finish in the top three, pass checkpoints, collect crystals and avoid obstacles.'},
{id:'leap',name:'Cloudstep Expedition',tag:'JUMPING ADVENTURE',icon:'↟',colour:'#a9d9ff',desc:'Leap between floating islands and find the sky portal.',help:'Move left and right. Press Jump or Space to leap. Collect the required relics before the portal. Landing sets a checkpoint; falling costs life.'},
{id:'tower',name:'Crystal Keep',tag:'TOWER DEFENCE',icon:'♜',colour:'#d3b6ff',desc:'Build and upgrade a defence network to protect your crystal.',help:'Tap an empty build pad to place a tower. Tap a tower to select it, then Upgrade. Build energy is earned during this run.'},
{id:'dodge',name:'Meteor Meadow',tag:'DODGE & SURVIVE',icon:'☄',colour:'#ffb9bd',desc:'Read danger zones, gather stars and survive the meteor storm.',help:'Move away from warning rings and flying meteors. Pulse clears nearby danger. Collect the required stars and survive until the timer ends.'},
{id:'maze',name:'Relic Run',tag:'MAZE ADVENTURE',icon:'◇',colour:'#a0ede0',desc:'Explore a fresh labyrinth, find three relics and unlock the portal.',help:'Use the joystick or arrows. Collect all three relics, then reach the portal. Ping reveals the next relic and briefly freezes the roaming warden.'},
{id:'space',name:'Orbit Rangers',tag:'SPACE BLASTER',icon:'⌁',colour:'#b7c4ff',desc:'Pilot a pet starship through drifting drones and enemy fire.',help:'Move with the joystick. Hold Zap or Space to fire your equipped weapon upward. Clear the drones, then defeat the Orbit Guardian.'},
{id:'memory',name:'Echo Vault',tag:'MEMORY CHALLENGE',icon:'▧',colour:'#efb5df',desc:'Remember the vault’s symbols and uncover every matching pair.',help:'Study the opening preview. Tap two cards to find a match. A mismatch costs one heart. Two hints can reveal the symbols briefly. Build matching streaks for bonus points.'}
];
function selectedGame(){return GAME_MODES.find(m=>m.id===profile.gameType)||GAME_MODES[0]}
function gameArtwork(m){const forms={arena:'<circle cx="85" cy="62" r="27" fill="none" stroke="currentColor" stroke-width="8"/><path d="M84 25V99M49 62H120" stroke="currentColor" stroke-width="5"/>',rally:'<path d="M51 63L65 33H113L128 63V90H51Z" fill="currentColor"/><path d="M72 41H107L114 60H63Z" fill="#303347"/><circle cx="64" cy="90" r="11" fill="#29263d"/><circle cx="116" cy="90" r="11" fill="#29263d"/>',leap:'<path d="M35 89H79V102H35M111 53H160V66H111" stroke="currentColor" stroke-width="10"/><path d="M66 74Q83 18 123 40" fill="none" stroke="currentColor" stroke-width="5" stroke-dasharray="7 5"/>',tower:'<path d="M62 37H80V51H99V37H117V101H62Z" fill="currentColor"/><path d="M76 99V76Q89 62 103 76V99" fill="#303347"/>',dodge:'<circle cx="104" cy="72" r="25" fill="currentColor"/><path d="M45 24L90 56M75 13L109 50M28 52L79 75" stroke="currentColor" stroke-width="8" stroke-linecap="round"/>',maze:'<path d="M35 30H145V101H35V52H112V80H68" fill="none" stroke="currentColor" stroke-width="10" stroke-linecap="square"/>',space:'<path d="M91 19L115 64 143 91 110 86 91 106 72 86 39 91 67 64Z" fill="currentColor"/><circle cx="91" cy="65" r="13" fill="#303347"/>',memory:'<rect x="39" y="24" width="47" height="75" rx="8" fill="currentColor"/><rect x="99" y="24" width="47" height="75" rx="8" fill="currentColor"/><path d="M62 43L76 62 62 81 48 62Z M122 43L136 62 122 81 108 62Z" fill="#303347"/>'};return `<svg viewBox="0 0 180 120" aria-hidden="true" style="color:${m.colour}"><ellipse cx="90" cy="104" rx="70" ry="11" fill="#11112344"/>${forms[m.id]}</svg>`}
function gameModeCards(){return `<section class="game-library"><div class="section-title"><div><h2>Eight ways to play. One curious mind.</h2><p>Choose an original game, a colour theme and your fields. Every run begins with ten questions.</p></div><span class="count">8 ORIGINAL GAMES</span></div><div class="game-grid">${GAME_MODES.map(m=>`<button data-game="${m.id}" aria-pressed="${selectedGame().id===m.id}" class="game-card ${selectedGame().id===m.id?'selected':''}" style="--game-colour:${m.colour}">${gameArtwork(m)}<small>${m.tag}</small><h3>${m.name} ${selectedGame().id===m.id?'✓':''}</h3><p>${m.desc}</p></button>`).join('')}</div></section>`}
const eightGameHome=home;home=function(){const html=eightGameHome();return html.replace('<section class="field-shortcuts">',gameModeCards()+'<section class="field-shortcuts">').replace('Enter the arena <span','Play '+selectedGame().name+' <span')};
const originalDifficultyCards=difficultyCards;difficultyCards=function(){if(selectedGame().id==='arena'||live)return originalDifficultyCards();return `<section class="difficulty-section"><div class="section-title"><div><h2>Choose your challenge</h2><p>Game speed and obstacles scale with your level too.</p></div></div><div class="difficulty-cards">${Object.values(BATTLE_MODES).map(m=>`<button class="difficulty-card ${selectedMode().id===m.id?'selected':''}" data-difficulty="${m.id}" aria-pressed="${selectedMode().id===m.id}" style="--mode-colour:${m.colour}"><span class="difficulty-stars">${'◆'.repeat(m.shots)}</span><h3>${m.name}</h3><p>${m.id==='scout'?'A gentler pace':m.id==='expert'?'Extra pressure and hazards':'The full adventure'}</p><small>${m.id==='expert'?'For experienced players':'Learn the rhythm. Build your skill.'}</small></button>`).join('')}</div></section>`};
function miniRandom(a){a.seed=(a.seed*1664525+1013904223)>>>0;return a.seed/4294967296}
function miniDamage(g,amount=1){if(g.invincible>0)return;g.hp=Math.max(0,g.hp-amount);g.invincible=1.2;GameAudio.effect('hurt')}
function miniInput(){let x=+!!(keys.ArrowRight||keys.d)-+!!(keys.ArrowLeft||keys.a),y=+!!(keys.ArrowDown||keys.s)-+!!(keys.ArrowUp||keys.w);if(stick.pointerId!==null){x=stick.x;y=stick.y}const mag=Math.max(1,Math.hypot(x,y));return{x:x/mag,y:y/mag,fire:!!keys[' ']||firePointerId!==null}}
function makeMiniState(g,type){const level=playerLevel(),factor=(selectedMode().id==='scout'?.82:selectedMode().id==='expert'?1.3:1)+level*.006;return{type,level,factor,seed:Math.floor(Math.random()*0xffffffff),clock:0,score:0,tick:0,objects:[],shots:[],spawn:0,action:0,energy:1,goal:0,progress:0,...{}}}
function initialiseMini(g,type){g.alt=makeMiniState(g,type);const a=g.alt;g.w=1000;g.h=650;const canvas=$('#arena');canvas.width=1000;canvas.height=650;g.x=500;g.y=500;g.invincible=2;g.elapsed=0;g.kills=0;g.wave=1;g.prepared=false;g.map=selectedMap();g.walls=[];g.bullets=[];g.enemyShots=[];g.enemies=[];
 if(type==='rally'){g.time=100;a.goal=12500+a.level*65;a.distance=0;g.y=495;g.x=roadCentre(g,0)}
 if(type==='leap'){g.time=150;a.goal=6600+a.level*35;a.camera=0;a.vy=0;a.grounded=false;a.checkpoint={x:80,y:500};a.platforms=[];let x=0,y=540;while(x<a.goal+300){const width=x===0?300:150+miniRandom(a)*90;a.platforms.push({x,y,w:width,h:30,gem:x>0&&!((a.platforms.length)%3),drone:x>0&&a.platforms.length%4===0});x+=width+55+miniRandom(a)*(45+Math.min(55,a.level));y=Math.max(280,Math.min(550,y+(miniRandom(a)-.5)*130))}a.goal=a.platforms.at(-1).x+70;g.x=85;g.y=500}
 if(type==='tower'){g.time=180;a.path=a.level<25?[[20,150],[270,150],[270,430],[650,430],[650,220],[980,220]]:[[20,130],[230,130],[230,480],[510,480],[510,250],[750,250],[750,430],[980,430]];a.funds=80;a.towers=[];a.slots=[];a.maxWaves=5+Math.floor(a.level/12);a.wave=0;a.toSpawn=0;a.waveWait=2;a.selected=-1;for(let y=100;y<590;y+=95)for(let x=90;x<940;x+=110)if(pathDistance(a.path,x,y)>58)a.slots.push({x,y});g.x=930;g.y=a.path.at(-1)[1]+90}
 if(type==='dodge'){g.time=75;a.spawn=.5;a.stars=0;g.x=500;g.y=365}
 if(type==='space'){g.time=110;a.goal=30+Math.floor(a.level*.6);a.spawn=1;g.x=500;g.y=525}
 if(type==='maze'){g.time=150;makeRelicMaze(g);a.goal=3}
 if(type==='memory'){g.time=150;a.pairs=a.level>=25?12:8;a.cols=a.pairs===12?6:4;a.rows=4;a.cards=shuffle(Array.from({length:a.pairs},(_,i)=>[i,i]).flat()).map((symbol,i)=>({symbol,matched:false,index:i}));a.flipped=[];a.preview=a.level>=35?2.1:3.8;a.lock=0;a.goal=a.pairs;a.progress=0}
 g.maxTime=g.time;canvas.setAttribute('aria-label',selectedGame().name+'. '+selectedGame().help);$('#arena-subtitle').textContent=selectedGame().name+' · '+g.map.name+' · Level '+a.level;$('#map-name').textContent=g.map.name;document.querySelector('.title-row h1').textContent=selectedGame().name;document.body.dataset.game=type;const main=document.querySelector('.fire-button strong');if(main)main.textContent=({rally:'BOOST',leap:'JUMP',tower:'UPGRADE',dodge:'PULSE',maze:'PING',space:'ZAP',memory:'HINT'})[type];document.querySelector('.fire-button')?.setAttribute('aria-label',({rally:'Boost kart',leap:'Jump',tower:'Upgrade selected tower',dodge:'Pulse away nearby meteors',maze:'Ping the next relic',space:'Fire equipped space blaster',memory:'Reveal a brief memory hint'})[type]);document.querySelector('.super-button')?.setAttribute('aria-label','Special action');const caption=document.querySelector('.ammo-label');if(caption)caption.innerHTML=(type==='tower'?'BUILD ':type==='space'?'ENERGY ':'SPECIAL ')+'<span id="ammo"></span>';document.querySelector('.super-button strong').textContent=type==='leap'?'BLAST':'SPECIAL';document.querySelector('.recharge-button').style.display='none';applyBattleControls();
}
const selectedGameStart=startArena;startArena=function(subject){selectedGameStart(subject);if(live||selectedGame().id==='arena'){document.body.dataset.game='arena';return}initialiseMini(game,selectedGame().id);const title=document.querySelector('#modal-title');if(title)title.textContent=selectedGame().name+': power up with knowledge.';document.querySelector('#modal-content .feedback')?.insertAdjacentHTML('afterend',`<p class="feedback">${selectedGame().help}</p>`);const paragraphs=document.querySelectorAll('#modal-content .feedback');if(paragraphs[2])paragraphs[2].textContent='Finish all ten questions, then start your adventure. Every correct answer adds one heart.'};
const miniPrepResults=preparationResults;preparationResults=function(){miniPrepResults();if(game?.alt){const button=document.querySelector('[data-action="enter-battle"]');if(button)button.textContent='Start '+selectedGame().name+' →';if(game.alt.type==='tower')game.alt.funds=80+game.questionsRight*4}};
const miniStart=enterPreparedBattle;enterPreparedBattle=function(){miniStart();if(game?.alt){last=performance.now();game.alt.clock=0;game.invincible=2;$('#arena').focus()}};
function roadCentre(g,d){const curve=g.map.curve||1;return g.w/2+Math.sin(d*.0014*curve)*145+Math.sin(d*.00051*curve+((g.map.baseIndex||0)*.5))*50}
function updateRally(g,dt,input){const a=g.alt,boost=(input.fire||a.action>0)&&a.energy>0,speed=(210+a.level*.7)*a.factor*(boost?1.5:1);a.distance+=speed*dt;a.progress=Math.min(a.goal,a.distance);a.energy=Math.max(0,Math.min(1,a.energy+(boost?-.35:.15)*dt));g.x=Math.max(70,Math.min(930,g.x+input.x*Math.max(420,(210+a.level*.7)*a.factor*1.15)*dt));const centre=roadCentre(g,a.distance);if(Math.abs(g.x-centre)>(g.map.routeWidth||190))miniDamage(g,1);a.spawn-=dt;if(a.spawn<=0){a.spawn=Math.max(.38,.85/a.factor);a.objects.push({d:a.distance+650,lane:(miniRandom(a)-.5)*330,kind:miniRandom(a)<.27?'crystal':'cone',hit:false})}for(const o of a.objects){o.x=roadCentre(g,o.d)+o.lane;o.y=g.y-(o.d-a.distance);if(!o.hit&&Math.abs(o.y-g.y)<43&&Math.abs(o.x-g.x)<39){o.hit=true;if(o.kind==='crystal'){a.crystals=(a.crystals||0)+1;a.score+=30;a.energy=Math.min(1,a.energy+.2);GameAudio.effect('pickup')}else miniDamage(g,1+Math.floor(a.level/20))}}a.objects=a.objects.filter(o=>o.y<720&&!o.hit);if(a.distance>=a.goal)finishMini(true)}
function updateLeap(g,dt,input){const a=g.alt;const oldY=g.y;g.x=Math.max(35,g.x+input.x*(265+a.level)*dt);if((input.fire||a.action>0)&&a.grounded){a.vy=-555;a.grounded=false;a.action=0;GameAudio.effect('dash')}a.vy+=1120*dt;g.y+=a.vy*dt;a.grounded=false;for(const p of a.platforms){if(g.x>p.x-12&&g.x<p.x+p.w+12&&oldY<=p.y+3&&g.y>=p.y&&a.vy>=0){g.y=p.y;a.vy=0;a.grounded=true;a.checkpoint={x:Math.max(p.x+30,Math.min(p.x+p.w-30,g.x)),y:p.y};if(p.gem&&!p.collected&&Math.abs(g.x-(p.x+p.w/2))<40){p.collected=true;a.score+=40;GameAudio.effect('pickup')}}if(p.drone){const ex=p.x+p.w/2+Math.sin(a.clock*2)*p.w*.35;if(Math.abs(g.x-ex)<34&&Math.abs(g.y-(p.y-25))<65)miniDamage(g,1+Math.floor(a.level/22))}}if(g.y>800){miniDamage(g,2);g.x=a.checkpoint.x;g.y=a.checkpoint.y-15;a.vy=0}a.camera=Math.max(0,g.x-300);a.progress=Math.max(a.progress,g.x);g.moving=Math.abs(input.x)>.1;if(g.x>=a.goal&&a.grounded)finishMini(true)}
function segmentDistance(x,y,p,q){const dx=q[0]-p[0],dy=q[1]-p[1],t=Math.max(0,Math.min(1,((x-p[0])*dx+(y-p[1])*dy)/(dx*dx+dy*dy||1)));return Math.hypot(x-(p[0]+dx*t),y-(p[1]+dy*t))}
function pathDistance(path,x,y){return Math.min(...path.slice(1).map((p,i)=>segmentDistance(x,y,path[i],p)))}
function towerTap(g,x,y){const a=g.alt,slot=a.slots.find(p=>Math.hypot(p.x-x,p.y-y)<43);if(!slot)return;const existing=a.towers.findIndex(t=>t.x===slot.x&&t.y===slot.y);if(existing>=0){a.selected=existing;return}if(a.funds<25){toast('A tower costs 25 build energy. Defeat bots to earn more.');return}a.funds-=25;a.towers.push({x:slot.x,y:slot.y,level:1,cooldown:0});a.selected=a.towers.length-1;GameAudio.effect('pickup')}
function upgradeTower(g){const a=g.alt,t=a.towers[a.selected];if(!t){toast('Tap a tower to select it first.');return}const cost=20*t.level;if(t.level>=4){toast('This tower is fully upgraded.');return}if(a.funds<cost){toast('Upgrade costs '+cost+' build energy.');return}a.funds-=cost;t.level++;GameAudio.effect('unlock')}
function updateTower(g,dt){const a=g.alt;if(a.toSpawn===0&&!a.objects.length){a.waveWait-=dt;if(a.waveWait<=0){if(a.wave>=a.maxWaves){finishMini(true);return}a.wave++;a.toSpawn=4+a.wave;a.spawn=0;a.waveWait=2.5;GameAudio.effect('wave')}}if(a.toSpawn>0){a.spawn-=dt;if(a.spawn<=0){a.spawn=.75;a.toSpawn--;const hp=(7+a.wave*2+a.level*.35)*a.factor;a.objects.push({x:a.path[0][0],y:a.path[0][1],segment:1,hp,maxHp:hp,speed:55+a.wave*3+a.level*.3})}}for(const e of a.objects){const end=a.path[e.segment],d=Math.hypot(end[0]-e.x,end[1]-e.y);if(d<e.speed*dt+1){e.x=end[0];e.y=end[1];e.segment++;if(e.segment>=a.path.length){g.hp=Math.max(0,g.hp-1);e.hp=0;e.escaped=true;GameAudio.effect('hurt')}}else{e.x+=(end[0]-e.x)/d*e.speed*dt;e.y+=(end[1]-e.y)/d*e.speed*dt}}for(const t of a.towers){t.cooldown-=dt;if(t.cooldown>0)continue;const target=a.objects.filter(e=>e.hp>0&&Math.hypot(e.x-t.x,e.y-t.y)<150+t.level*22).sort((x,y)=>y.segment-x.segment)[0];if(target){target.hp-=2+t.level*2+g.hero.damage*.45;t.cooldown=.7/(1+t.level*.12);a.shots.push({x:t.x,y:t.y,tx:target.x,ty:target.y,life:.18});GameAudio.effect('shoot')}}a.objects=a.objects.filter(e=>{if(e.hp>0)return true;if(!e.escaped){a.funds+=7;a.score+=35;GameAudio.effect('defeat')}return false});a.shots=a.shots.filter(s=>(s.life-=dt)>0);a.progress=a.wave;g.wave=a.wave;g.totalWaves=a.maxWaves}
function updateDodge(g,dt,input){const a=g.alt;g.x=Math.max(45,Math.min(955,g.x+input.x*g.speed*dt));g.y=Math.max(80,Math.min(600,g.y+input.y*g.speed*dt));g.moving=!!(input.x||input.y);a.spawn-=dt;if(a.spawn<=0){a.spawn=.7/a.factor;const warning=miniRandom(a)<.6;a.objects.push(warning?{kind:'warning',x:miniRandom(a)<.5?g.x:70+miniRandom(a)*860,y:miniRandom(a)<.5?g.y:100+miniRandom(a)*450,age:0,r:38+a.level*.4}:{kind:'meteor',x:30+miniRandom(a)*940,y:-40,dx:(miniRandom(a)-.5)*130,dy:135+a.level*2,age:0})}for(const o of a.objects){o.age+=dt;if(o.kind==='meteor'){o.x+=o.dx*dt;o.y+=o.dy*dt;if(Math.hypot(o.x-g.x,o.y-g.y)<38)miniDamage(g,1+Math.floor(a.level/20))}else if(o.age>1.15&&o.age<1.45&&Math.hypot(o.x-g.x,o.y-g.y)<o.r+20)miniDamage(g,2)}a.objects=a.objects.filter(o=>o.kind==='warning'?o.age<1.7:o.y<720);a.progress=a.clock;if(g.time<=0)finishMini(true)}
function updateSpace(g,dt,input){const a=g.alt;g.x=Math.max(45,Math.min(955,g.x+input.x*(g.speed+20)*dt));g.y=Math.max(105,Math.min(590,g.y+input.y*g.speed*dt));g.moving=!!(input.x||input.y);if(input.fire||a.action>0)miniAction(g);a.spawn-=dt;if(a.spawn<=0){a.spawn=Math.max(.35,1.1/a.factor);a.objects.push({x:70+miniRandom(a)*860,y:-40,hp:3+Math.floor(a.level*.25),maxHp:3+Math.floor(a.level*.25),speed:50+a.level,fire:1+miniRandom(a),phase:miniRandom(a)*6})}for(const e of a.objects){e.y+=e.speed*dt;e.x+=Math.sin(a.clock*2+e.phase)*30*dt;e.fire-=dt;if(e.fire<0){e.fire=1.5;const angle=Math.atan2(g.y-e.y,g.x-e.x);a.shots.push({x:e.x,y:e.y,dx:Math.cos(angle)*(145+a.level),dy:Math.sin(angle)*(145+a.level),life:6,enemy:true})}if(e.y>660){miniDamage(g,1);e.hp=0;e.escaped=true}if(Math.hypot(e.x-g.x,e.y-g.y)<48)miniDamage(g,2)}for(const s of a.shots){s.x+=s.dx*dt;s.y+=s.dy*dt;s.life-=dt;if(s.enemy){if(Math.hypot(s.x-g.x,s.y-g.y)<30){miniDamage(g,1);s.life=0}}else{const e=a.objects.find(e=>e.hp>0&&Math.hypot(e.x-s.x,e.y-s.y)<(e.guardian?62:31));if(e){e.hp-=s.damage;if(!advancePiercingShot(s,{r:23}))s.life=0}}}a.shots=a.shots.filter(s=>s.life>0&&s.y>-30&&s.y<720);a.objects=a.objects.filter(e=>{if(e.hp>0)return true;if(!e.escaped){a.progress++;a.score+=40;GameAudio.effect('defeat')}return false});if(a.progress>=a.goal)finishMini(true)}
function makeRelicMaze(g){const a=g.alt;a.cols=a.level>=40?23:a.level>=25?19:a.level>=10?17:13;a.rows=a.level>=25?13:9;a.cell=Math.min(936/a.cols,540/a.rows);a.ox=(1000-a.cols*a.cell)/2;a.oy=55;a.cells=Array.from({length:a.cols*a.rows},()=>({walls:[true,true,true,true],visited:false}));const stack=[0];a.cells[0].visited=true;while(stack.length){const i=stack.at(-1),x=i%a.cols,y=Math.floor(i/a.cols),opts=[[0,-1],[1,0],[0,1],[-1,0]].map(([dx,dy],dir)=>({x:x+dx,y:y+dy,dir})).filter(p=>p.x>=0&&p.y>=0&&p.x<a.cols&&p.y<a.rows&&!a.cells[p.y*a.cols+p.x].visited);if(!opts.length){stack.pop();continue}const p=opts[Math.floor(miniRandom(a)*opts.length)],j=p.y*a.cols+p.x;a.cells[i].walls[p.dir]=false;a.cells[j].walls[(p.dir+2)%4]=false;a.cells[j].visited=true;stack.push(j)}a.mazeWalls=[];a.cells.forEach((cell,i)=>{const x=a.ox+(i%a.cols)*a.cell,y=a.oy+Math.floor(i/a.cols)*a.cell;if(cell.walls[0])a.mazeWalls.push({x,y,w:a.cell,h:6});if(cell.walls[3])a.mazeWalls.push({x,y,w:6,h:a.cell});if(i%a.cols===a.cols-1&&cell.walls[1])a.mazeWalls.push({x:x+a.cell,y,w:6,h:a.cell});if(Math.floor(i/a.cols)===a.rows-1&&cell.walls[2])a.mazeWalls.push({x,y:y+a.cell,w:a.cell,h:6})});g.walls=a.mazeWalls;g.x=a.ox+a.cell/2;g.y=a.oy+a.cell/2;a.relics=[Math.floor(a.cells.length*.28),Math.floor(a.cells.length*.58),Math.floor(a.cells.length*.82)].map(index=>({index,found:false}));a.exit=a.cells.length-1;a.hint=0}
function mazePoint(a,index){return{x:a.ox+(index%a.cols+.5)*a.cell,y:a.oy+(Math.floor(index/a.cols)+.5)*a.cell}}
function updateMaze(g,dt,input){const a=g.alt;moveBody(g,g,input.x*150*dt,input.y*150*dt,Math.min(12,a.cell*.24));g.moving=!!(input.x||input.y);for(const r of a.relics){const p=mazePoint(a,r.index);if(!r.found&&Math.hypot(p.x-g.x,p.y-g.y)<a.cell*.36){r.found=true;a.progress++;a.score+=100;GameAudio.effect('pickup')}}a.hint=Math.max(0,a.hint-dt);const exit=mazePoint(a,a.exit);if(a.progress===3&&Math.hypot(exit.x-g.x,exit.y-g.y)<a.cell*.4)finishMini(true)}
function memoryRect(g,i){const a=g.alt,width=Math.min(110,780/a.cols),height=95,gap=14,left=(1000-(a.cols*width+(a.cols-1)*gap))/2;return{x:left+(i%a.cols)*(width+gap),y:95+Math.floor(i/a.cols)*(height+gap),w:width,h:height}}
