function updateMemory(g,dt){const a=g.alt;a.preview=Math.max(0,a.preview-dt);if(a.lock>0){a.lock-=dt;if(a.lock<=0){a.flipped=[];g.hp=Math.max(0,g.hp-1);GameAudio.effect('wrong')}}}
function miniAction(g=game){if(!g?.alt||g.paused)return;const a=g.alt;if(a.type!=='space'){if(a.actionCooldown>0)return;a.actionCooldown=.2}if(a.type==='leap'){a.action=.25;return}if(a.type==='tower'){upgradeTower(g);return}if(a.type==='space'){if(g.cooldown>0||g.ammo<=0)return;const w=weaponFor(g.weapon);for(let i=0;i<w.shots;i++){const angle=-Math.PI/2+(i-(w.shots-1)/2)*w.spread;a.shots.push({x:g.x,y:g.y-45,dx:Math.cos(angle)*550,dy:Math.sin(angle)*550,life:1.6,damage:g.hero.damage*w.damage,pierce:w.pierce,colour:w.colour})}g.cooldown=g.hero.shotDelay*w.delay;g.ammo--;GameAudio.effect('shoot');return}if(a.energy<.5)return;a.energy-=.5;if(a.type==='rally')a.action=1.3;if(a.type==='dodge'){a.objects=a.objects.filter(o=>Math.hypot(o.x-g.x,o.y-g.y)>180);a.score+=5;GameAudio.effect('super')}if(a.type==='maze'){a.hint=4;GameAudio.effect('pickup')}if(a.type==='memory'){a.hintsUsed=(a.hintsUsed||0)+1;a.preview=1.5;GameAudio.effect('pickup')}}
