function miniPet(c,g,x,y,size=75){const img=getAvatarSprite(g.hero);c.save();if(g.invincible>0&&Math.floor(g.elapsed*8)%2)c.globalAlpha=.5;if(img?.complete&&img.naturalWidth)c.drawImage(img,x-size/2,y-size*1.13,size,size*1.13);else{ellipse(c,x,y-size*.4,size*.3,size*.38,g.hero.colour);ellipse(c,x-10,y-size*.45,3,4,'#303344');ellipse(c,x+10,y-size*.45,3,4,'#303344')}c.restore()}
