function drawRally(c,g){const a=g.alt,m=g.map;miniBackdrop(c,g);c.lineCap='round';for(const[width,colour]of [[460,m.edge],[425,m.stone],[380,m.path]]){c.strokeStyle=colour;c.lineWidth=width-(190-(g.map.routeWidth||190))*2;c.beginPath();for(let y=-50;y<750;y+=18){const x=roadCentre(g,a.distance+g.y-y);if(y===-50)c.moveTo(x,y);else c.lineTo(x,y)}c.stroke()}c.strokeStyle='#fff3c777';c.lineWidth=5;c.setLineDash([25,34]);c.lineDashOffset=a.distance%59;c.beginPath();for(let y=-50;y<750;y+=18){const x=roadCentre(g,a.distance+g.y-y);if(y===-50)c.moveTo(x,y);else c.lineTo(x,y)}c.stroke();c.setLineDash([]);for(const o of a.objects){if(o.kind==='crystal')miniGem(c,o.x,o.y);else{c.fillStyle='#f28e6e';c.beginPath();c.moveTo(o.x,o.y-23);c.lineTo(o.x-22,o.y+19);c.lineTo(o.x+22,o.y+19);c.closePath();c.fill();c.fillStyle='#ffe6b4';c.fillRect(o.x-13,o.y,26,6)}}c.save();c.translate(g.x,g.y);ellipse(c,0,25,42,18,'#20344355');roundRect(c,-43,-30,16,63,5,'#293443');roundRect(c,27,-30,16,63,5,'#293443');roundRect(c,-31,-47,62,85,16,m.accent,'#3e3b59');roundRect(c,-22,-20,44,43,11,'#30334d');miniPet(c,g,0,14,58);if(a.action>0){c.fillStyle='#ffdb91';c.beginPath();c.moveTo(-15,39);c.lineTo(0,74);c.lineTo(15,39);c.fill()}c.restore()}
