function drawSpace(c,g){const a=g.alt;miniBackdrop(c,g,true);for(const e of a.objects){c.save();c.translate(e.x,e.y);c.fillStyle='#dc99aa';c.beginPath();c.moveTo(0,27);c.lineTo(-32,-13);c.lineTo(-13,-25);c.lineTo(13,-25);c.lineTo(32,-13);c.closePath();c.fill();ellipse(c,0,-5,12,10,'#433c67');ellipse(c,0,-5,5,5,'#ffeab8');c.restore()}for(const s of a.shots){c.strokeStyle=s.enemy?'#ffbea8':s.colour||'#d5fa59';c.lineWidth=s.enemy?8:5;c.beginPath();c.moveTo(s.x,s.y);c.lineTo(s.x-s.dx*.03,s.y-s.dy*.03);c.stroke()}c.save();c.translate(g.x,g.y);c.fillStyle=g.map.accent;c.beginPath();c.moveTo(0,-56);c.lineTo(46,35);c.lineTo(17,25);c.lineTo(0,46);c.lineTo(-17,25);c.lineTo(-46,35);c.closePath();c.fill();ellipse(c,0,0,22,29,'#33425e');miniPet(c,g,0,17,49);c.restore()}
function drawMaze(c,g){const a=g.alt;miniBackdrop(c,g);roundRect(c,a.ox-8,a.oy-8,a.cols*a.cell+16,a.rows*a.cell+16,12,g.map.path);c.fillStyle=g.map.edge;for(const r of a.mazeWalls)c.fillRect(r.x,r.y,r.w,r.h);for(const r of a.relics)if(!r.found){const p=mazePoint(a,r.index);miniGem(c,p.x,p.y,g.map.accent,Math.min(13,a.cell*.25))}const exit=mazePoint(a,a.exit);c.strokeStyle=a.progress===3?'#e3ffad':'#b994a3';c.lineWidth=4;c.beginPath();c.arc(exit.x,exit.y,a.cell*.32,0,7);c.stroke();if(a.hint>0){const target=a.relics.find(r=>!r.found),p=mazePoint(a,target?target.index:a.exit);c.strokeStyle='#ffec9e';c.lineWidth=4;c.beginPath();c.arc(p.x,p.y,Math.min(23,a.cell*.45),0,7);c.stroke()}miniPet(c,g,g.x,g.y+17,Math.min(49,a.cell*.95))}
