const eightRender=renderArena;renderArena=function(g){if(!g.alt)return eightRender(g);const c=g.ctx;c.clearRect(0,0,1000,650);({rally:drawRally,leap:drawLeap,tower:drawTower,dodge:drawDodge,space:drawSpace,maze:drawMaze,memory:drawMemory})[g.alt.type](c,g);if(!movementHUDDue(g))return;$('#hp').textContent='♥ '+Math.max(0,g.hp)+' / '+g.maxHp;const a=g.alt;$('#wave').textContent=({rally:'ROUTE '+Math.floor(a.progress/100)+' / '+Math.floor(a.goal/100),leap:'EXPEDITION '+Math.floor(a.progress/a.goal*100)+'%',tower:'WAVE '+a.wave+' / '+a.maxWaves,dodge:'SURVIVED '+Math.floor(a.progress)+'s',space:'DRONES '+a.progress+' / '+a.goal,maze:'RELICS '+a.progress+' / 3',memory:'PAIRS '+a.progress+' / '+a.goal})[a.type];$('#timer').textContent=Math.floor(Math.ceil(Math.max(0,g.time))/60)+':'+String(Math.ceil(Math.max(0,g.time))%60).padStart(2,'0');const life=document.querySelector('#life-fill');if(life)life.style.width=Math.max(0,g.hp/g.maxHp)*100+'%';$('#charge').textContent=Math.round(a.energy*100)+'%';$('#ammo').textContent=a.type==='space'?g.ammo:a.type==='tower'?a.funds:Math.round(a.energy*100)+'%';const bars=document.querySelector('#energy-pips'),count=a.type==='space'?g.ammo:Math.round(a.energy*g.maxAmmo);if(bars&&g.miniEnergyBars!==count){g.miniEnergyBars=count;bars.innerHTML=Array.from({length:g.maxAmmo},(_,i)=>'<i class="'+(i<count?'filled':'')+'"></i>').join('')}};
function finishMini(win){const g=game;if(!g?.alt)return;const a=g.alt,m=GAME_MODES.find(m=>m.id===a.type),score=Math.floor(a.score+g.questionsRight*40+(win?250+Math.max(0,g.time)*2:0)),key='game:'+a.type+':'+g.map.id+':'+g.mode.id;profile.matches++;if(win){profile.wins++;profile.xp+=g.mode.bonus;profile.coins+=score}profile.personalBests??={};profile.personalBests[key]=Math.max(profile.personalBests[key]||0,score);save();game=null;quiz=null;cancelAnimationFrame(raf);GameAudio.effect(win?'win':'finish');openModal(`${topModal(m.name.toUpperCase()+' · RESULTS')}<div class="results"><div class="result-emblem">${win?'✦':'⚑'}</div><h2 id="modal-title">${win?'Adventure complete!':'Another chance to grow.'}</h2><p>${m.name} · ${g.map.name} · ${g.mode.name}</p><div class="match-score">${score}<small>SCORE POINTS</small></div><div class="results-stats"><div><b>+${win?score:0}</b><span>LEVEL-CLEAR CREDITS · 1 POINT = 1 CREDIT</span></div><div><b>${g.questionsRight}/10</b><span>WARM-UP ANSWERS</span></div></div><p class="notice">${win?'Your level-clear points were added to your credits.':'Question credits you earned are already saved.'} Question bonuses are awarded separately.</p><div class="modal-actions" style="justify-content:center"><button class="primary" data-rematch="${g.subject}">Play again →</button><button class="secondary" data-action="done">Choose another game</button></div></div>`)}
